  "label": "NOT_ENOUGH_INFO",
  "evidence_ids": [],
  "explanation": "Báo cáo chỉ ghi nhận việc đổi giờ sinh hoạt và số thành viên tăng diễn ra đồng thời nhưng không xác định mối quan hệ nhân quả giữa hai sự việc này."
}

{
  "id": "vg004",
  "label": "SUPPORTED",
  "evidence_ids": ["e1", "e2"],
  "explanation": "Cả hai bản kiểm kê số 1 và số 2 đều xác nhận nhà sinh hoạt Hạt Nắng có đúng 3 cửa ra vào."
}

 {
  "id": "vg005",
  "label": "NOT_ENOUGH_INFO",
  "evidence_ids": [],
  "explanation": "Tài liệu cung cấp thông tin về sân tập Bờ Trăng có mái che, nhưng không có mô tả về sân tập Bờ Nắng."
}

{
  "id": "vg011",
  "label": "SUPPORTED",
  "evidence_ids": [
    "e1",
    "e2"
  ],
  "explanation": "Đoạn e1 cho biết lớp dệt của trung tâm Hừng Đông học tại phòng Lá, và đoạn e2 xác nhận phòng dùng cho lớp dệt này có đúng 24 ghế."
}

 {
  "id": "vg019",
  "label": "REFUTED",
  "evidence_ids": [
    "e1"
  ],
  "explanation": "Biên bản kiểm kê xác nhận tủ sách Mạch Nguồn có 180 cuốn, không phải 200 cuốn."
}

{
  "id": "vg021",
  "label": "NOT_ENOUGH_INFO",
  "evidence_ids": [],
  "explanation": "Có hai nguồn tin cậy ngang nhau cung cấp số lượng học viên trái ngược nhau (22 và 25), và chưa có thông báo giải quyết sự khác biệt này."
}

{
  "id": "vg037",
  "label": "REFUTED",
  "evidence_ids": [
  "e1"
  ],
  "explanation": "Bằng chứng e1 xác nhận hội chợ Trăng Non chỉ diễn ra tại sân Đông và không có hoạt động nào tại sân Tây, trái ngược với claim."
}

{
  "id": "vg040",
  "label": "SUPPORTED",
  "evidence_ids": ["e1"],
  "explanation": "Trước khi sửa chữa phòng Sỏi có 50 ghế, sau sửa chữa có 60 ghế. Mức tăng là (60-50)/50 = 10/50 = 20%."
}

{
  "id": "vg045",
  "label": "NOT_ENOUGH_INFO",
  "evidence_ids": [],
  "explanation": "Thông tin về mái che được xác nhận, nhưng không có thông tin về hệ thống đèn chiếu sáng của sân Mây."
}
